#include "pattern_fixed_bridge.h"
#include <string.h>
static int valid_name(const char *name){unsigned i;if(!name)return 0;for(i=0;i<FM1_PROJECT_NAME_BYTES&&name[i];i++)if((unsigned char)name[i]<32u||(unsigned char)name[i]>126u)return 0;return i>0&&i<FM1_PROJECT_NAME_BYTES;}
static void working_name(uint32_t slot,char out[4]){unsigned n=(unsigned)slot+1u;out[0]='W';out[1]=(char)('0'+n/10u);out[2]=(char)('0'+n%10u);out[3]=0;}
int fm1_fixed_bridge_working_slot(const char name[PS_NAME_BYTES],unsigned slots){unsigned n,i;if(!slots||slots>FM1_FIXED_MAX_NAMED_SLOTS||!name||name[0]!='W'||name[1]<'0'||name[1]>'9'||name[2]<'0'||name[2]>'9'||name[3])return -2;for(i=4;i<PS_NAME_BYTES;i++)if(name[i])return -2;n=(unsigned)(name[1]-'0')*10u+(unsigned)(name[2]-'0');return n<=slots?(int)n-1:-2;}
int fm1_fixed_bridge_bind(fm1_fixed_bridge *b,const fm1_fixed_bridge_ops *ops){if(!b||b->busy||b->fault||!ops||!ops->prepare||!ops->open_pair||!ops->close_pair||!ops->activate||!ops->finish||!ops->named_slots||ops->named_slots>FM1_FIXED_MAX_NAMED_SLOTS)return PFS_INVALID;b->ops=ops;return PFS_OK;}
static int backend_write(fm1_fixed_bridge_transaction *t,uint32_t slot,const char *name,fm1_fixed_bridge_access *a){
 if(t->write_pair)return t->write_pair(t->write_ctx,slot,name,t->source,a->initializing,a->certify,a->context);
#if defined(FM1_PATTERN_STREAM_ONLY) && FM1_PATTERN_STREAM_ONLY
 return PS_INVALID;
#else
 return a->initializing?fm1_fixed_project_initialize(t->store,slot,name,t->source,t->payload,t->verify,t->preflight,t->preflight_ctx,a->certify,a->context):fm1_fixed_project_save(t->store,slot,name,t->source,t->payload,t->verify,t->preflight,t->preflight_ctx,a->certify,a->context);
#endif
}
static int write_one(fm1_fixed_bridge *b,const fm1_fixed_bridge_ops *ops,fm1_fixed_bridge_transaction *t,uint32_t slot,const char *name){fm1_fixed_bridge_access a;int rc,closed,opened;unsigned init;memset(&a,0,sizeof a);opened=ops->open_pair(ops->context,slot,&a);if(opened<0){b->fault=1;return FM1_PROJECT_ROLLBACK_FAILED;}if(opened!=1)return opened==2?PFS_FULL:PFS_INVALID;if(!a.certify||a.initializing>1)rc=PS_INVALID;else rc=backend_write(t,slot,name,&a);init=a.initializing;closed=ops->close_pair(ops->context,&a);if(closed!=1){b->fault=1;return FM1_PROJECT_ROLLBACK_FAILED;}if(rc!=PS_OK){if(rc==FM1_PROJECT_ROLLBACK_FAILED){b->fault=1;return FM1_PROJECT_ROLLBACK_FAILED;}if(init==1&&rc!=FM1_FIXED_FULL){b->fault=1;return FM1_PROJECT_ROLLBACK_FAILED;}return fm1_fixed_project_bridge_result(rc);}if(init==1&&ops->activate(ops->context,slot)!=1){b->fault=1;return FM1_PROJECT_ROLLBACK_FAILED;}return PFS_OK;}
int fm1_fixed_bridge_save(fm1_fixed_bridge *b,uint32_t slot,const char *name){fm1_fixed_bridge_transaction t;const fm1_fixed_bridge_ops *ops;int rc,finish,prepared,working;char workname[4];if(!b||b->busy||b->fault||!b->ops||!b->ops->named_slots||b->ops->named_slots>FM1_FIXED_MAX_NAMED_SLOTS||slot>=b->ops->named_slots||!valid_name(name))return PFS_INVALID;ops=b->ops;working_name(slot,workname);memset(&t,0,sizeof t);b->busy=1;prepared=ops->prepare(ops->context,slot,&t);if(prepared!=1){b->busy=0;if(prepared<0){b->fault=1;return FM1_PROJECT_ROLLBACK_FAILED;}return FM1_PROJECT_BUSY;}if(!t.source||(!t.write_pair&&(!t.store||!t.payload||!t.verify||!t.preflight)))rc=PFS_INVALID;else{rc=write_one(b,ops,&t,slot,name);if(rc==PFS_OK){working=write_one(b,ops,&t,FM1_FIXED_WORKING_SLOT,workname);if(working!=PFS_OK)rc=(working==FM1_PROJECT_ROLLBACK_FAILED||b->fault)?FM1_PROJECT_ROLLBACK_FAILED:FM1_PROJECT_WORKING_FAILED;else if(ops->commit_slot&&ops->commit_slot(ops->context,(int)slot)!=1){b->fault=1;rc=FM1_PROJECT_ROLLBACK_FAILED;}}}finish=ops->finish(ops->context);b->busy=0;if(finish!=1){b->fault=1;return FM1_PROJECT_ROLLBACK_FAILED;}return rc;}

int fm1_fixed_bridge_load(fm1_fixed_bridge *b,uint32_t slot){fm1_fixed_bridge_transaction t;fm1_fixed_bridge_access a;const fm1_fixed_bridge_ops *ops;int rc,adopted,closed,prepared,opened,staged,working;char workname[4];if(!b||b->busy||b->fault||!b->ops||!b->ops->named_slots||b->ops->named_slots>FM1_FIXED_MAX_NAMED_SLOTS||slot>=b->ops->named_slots)return PFS_INVALID;ops=b->ops;working_name(slot,workname);if(!ops->prepare_load||!ops->stage_load||!ops->adopt||!ops->recapture)return PFS_INVALID;memset(&t,0,sizeof t);memset(&a,0,sizeof a);b->busy=1;prepared=ops->prepare_load(ops->context,slot,&t);if(prepared!=1){b->busy=0;if(prepared<0){b->fault=1;return FM1_PROJECT_ROLLBACK_FAILED;}return FM1_PROJECT_BUSY;}opened=ops->open_pair(ops->context,slot,&a);if(opened<0){b->fault=1;rc=FM1_PROJECT_ROLLBACK_FAILED;}else if(opened!=1)rc=PFS_INVALID;else{if(!a.certify||a.initializing)rc=PFS_INVALID;else{staged=ops->stage_load(ops->context,slot,a.certify,a.context);if(staged<0){b->fault=1;rc=FM1_PROJECT_ROLLBACK_FAILED;}else rc=staged==1?PFS_OK:PFS_INVALID;}closed=ops->close_pair(ops->context,&a);if(closed!=1){b->fault=1;rc=FM1_PROJECT_ROLLBACK_FAILED;}}if(rc==PFS_OK){adopted=ops->adopt(ops->context);if(adopted!=1){rc=adopted<0?FM1_PROJECT_ROLLBACK_FAILED:PFS_INVALID;if(adopted<0)b->fault=1;}else if(ops->commit_slot&&ops->commit_slot(ops->context,(int)slot)!=1){b->fault=1;rc=FM1_PROJECT_ROLLBACK_FAILED;}else if((prepared=ops->recapture(ops->context,&t))!=1||!t.source||(!t.write_pair&&(!t.store||!t.payload||!t.verify||!t.preflight))){if(prepared<0){b->fault=1;rc=FM1_PROJECT_ROLLBACK_FAILED;}else rc=FM1_PROJECT_WORKING_FAILED;}else{working=write_one(b,ops,&t,FM1_FIXED_WORKING_SLOT,workname);if(working!=PFS_OK)rc=(working==FM1_PROJECT_ROLLBACK_FAILED||b->fault)?FM1_PROJECT_ROLLBACK_FAILED:FM1_PROJECT_WORKING_FAILED;}}if(ops->finish(ops->context)!=1){b->fault=1;rc=FM1_PROJECT_ROLLBACK_FAILED;}b->busy=0;return rc;}

int fm1_fixed_bridge_recover(fm1_fixed_bridge *b){fm1_fixed_bridge_transaction t;fm1_fixed_bridge_access a;const fm1_fixed_bridge_ops *ops;char name[PS_NAME_BYTES];int prepared,opened,staged,closed,adopted,selected=-2,rc;if(!b||b->busy||b->fault||!b->ops||!b->ops->named_slots||b->ops->named_slots>FM1_FIXED_MAX_NAMED_SLOTS)return PFS_INVALID;ops=b->ops;if(!ops->prepare_recovery||!ops->stage_working||!ops->adopt||!ops->commit_slot)return PFS_INVALID;memset(&t,0,sizeof t);memset(&a,0,sizeof a);memset(name,0xff,sizeof name);b->busy=1;prepared=ops->prepare_recovery(ops->context,&t);if(prepared!=1){b->busy=0;if(prepared<0){b->fault=1;return FM1_PROJECT_ROLLBACK_FAILED;}return prepared==2?FM1_PROJECT_SAFE_EMPTY:prepared==5?FM1_PROJECT_FOREIGN_WORKING:prepared==4?PFS_IO:prepared==3?PFS_INVALID:FM1_PROJECT_BUSY;}opened=ops->open_pair(ops->context,FM1_FIXED_WORKING_SLOT,&a);if(opened<0){b->fault=1;rc=FM1_PROJECT_ROLLBACK_FAILED;}else if(opened!=1)rc=PFS_INVALID;else{if(!a.certify||a.initializing)rc=PFS_INVALID;else{staged=ops->stage_working(ops->context,a.certify,a.context,name);if(staged<0){b->fault=1;rc=FM1_PROJECT_ROLLBACK_FAILED;}else if(staged!=1)rc=PFS_INVALID;else{selected=fm1_fixed_bridge_working_slot(name,ops->named_slots);rc=selected==-2?PFS_INVALID:PFS_OK;}}closed=ops->close_pair(ops->context,&a);if(closed!=1){b->fault=1;rc=FM1_PROJECT_ROLLBACK_FAILED;}}if(rc==PFS_OK){adopted=ops->adopt(ops->context);if(adopted!=1){rc=adopted<0?FM1_PROJECT_ROLLBACK_FAILED:PFS_INVALID;if(adopted<0)b->fault=1;}else if(ops->commit_slot(ops->context,selected)!=1){b->fault=1;rc=FM1_PROJECT_ROLLBACK_FAILED;}}if(ops->finish(ops->context)!=1){b->fault=1;rc=FM1_PROJECT_ROLLBACK_FAILED;}b->busy=0;return rc;}
